import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/saviors.json";
import potentials from "../../../data/potentials.json";
import FILTERS from "../../../data/filter_config.json";
import SORT_LIST from "../../../data/sort_config.json";

const ATTR_BASIC_SCORE = {
    NUAT_ORDER: 1,
    NUAT_CHAOS: 2,
    NUAT_SUN: 3,
    NUAT_MOON: 4,
    NUAT_STAR: 5,
};

const RARITY_BASIC_SCORE = {
    SR: 1,
    SSR: 2,
};

const normalizeSaviors = (originData) => {
    const entities = {};
    const ids = [];

    originData.forEach((savior) => {
        ids.push(savior.id);

        const parts = [savior.name.ko, savior.title.ko];
        const parts_ENG = [savior.name.en, savior.title.en];

        for (const resonance of savior.resonances) {
            if (resonance.potential) {
                const potential = potentials.find((p) => p.str_id === resonance.potential);
                parts.push(potential.name.ko);
                parts_ENG.push(potential.name.en);
            }
        }

        for (const skill of savior.skills) {
            parts.push(skill.name.ko, skill.levels.at(-1).skill_desc.ko);
            parts_ENG.push(skill.name.en, skill.levels.at(-1).skill_desc.en);
        }

        entities[savior.id] = {
            ...savior,
            searchText: parts.join(" "),
            searchText_ENG: parts_ENG.join(" "),
        };
    });

    ids.sort((a, b) => {
        const diff = RARITY_BASIC_SCORE[entities[b].rank] - RARITY_BASIC_SCORE[entities[a].rank];
        if (diff !== 0) return diff;

        const attrDiff = ATTR_BASIC_SCORE[entities[a].attr] - ATTR_BASIC_SCORE[entities[b].attr];
        if (attrDiff !== 0) return attrDiff;

        const lang = localStorage.getItem("language") || "ko";
        const locale = lang === "ko" ? "ko-KR" : "en-US";

        return entities[a].name[lang].localeCompare(entities[b].name[lang], locale);
    });

    return { ids, entities };
};

const normalized = normalizeSaviors(originData);

const saviorSlice = createSlice({
    name: "saviors",
    initialState: {
        ids: normalized.ids,
        entities: normalized.entities,
        filter: {
            rarity: FILTERS.SAVIOR_RARITY[0],
            attr: FILTERS.ATTRIBUTE[0],
            class: FILTERS.CLASS[0],
            order: SORT_LIST.SAVIOR_SORT[0],
        },
    },
    reducers: {
        changeFilter: (state, action) => {
            state.filter[action.payload.id] = action.payload.obj;
        },
    },
});

export const { changeFilter } = saviorSlice.actions;

export default saviorSlice.reducer;
