import React from "react";
import styles from "./full-screen-modal.module.css";
import { useDispatch, useSelector } from "react-redux";
import { inactive } from "../../../../store/reducers/toggle/fullScreenArcpintToggle";
import { UI_TEXT } from "../../../../constants";
import { getUIText } from "../../../../translation";

export default function FullScreenModal({ lang, savior }) {
    const fullscreenToggle = useSelector((state) => state.fullscreen.value);

    const dispatch = useDispatch();

    // const fitContent = savior?.name === "스칼렛(바니걸)" || savior?.name === "클레어(바니걸)" ? { width: "fit-content" } : {};

    if (savior)
        return (
            <div className={`${styles["modal"]} ${fullscreenToggle ? `${styles["active"]}` : ""}`} onClick={() => dispatch(inactive())}>
                <img src={`${process.env.PUBLIC_URL}/images/arcpoint/${savior.name["ko"]}(${savior.title["ko"]}).webp`} />
                <div className={styles["hint"]}>{getUIText(lang, "savior.modal.arcpoint.close")}</div>
            </div>
        );
}
