import { createSlice } from "@reduxjs/toolkit";

const langSlice = createSlice({
    name: "lang",
    initialState: {
        value: localStorage.getItem("language") || "ko",
    },
    reducers: {
        toggle: (state) => {
            state.value = state.value === "ko" ? "en" : "ko";
            localStorage.setItem("language", state.value);
        },
    },
});

export const { toggle } = langSlice.actions;

export default langSlice.reducer;
