import React, { useEffect, useState } from "react";
import styles from "./selected-arcana-list.module.css";
import { useSelector } from "react-redux";
import { v4 } from "uuid";
import getImageFileName from "../../functions/getImageFileName";
import { selectSelectedDeck } from "../../store/selectors/deckSelectors";
import { selectArcanaEntities } from "../../store/selectors/arcanaSelectors";

const standard = 110;

export default function SelectedArcanaList({ lang, setArcana }) {
    const deck = useSelector((state) => selectSelectedDeck(state));
    const arcanaEntities = useSelector((state) => selectArcanaEntities(state));

    const [left, setLeft] = useState(0);

    const judgeMobile = () => {
        const agent = navigator.userAgent.toLowerCase();

        return agent.indexOf("android") > -1 || agent.indexOf("iphone") > -1 || agent.indexOf("ipad") > -1;
    };

    useEffect(() => {
        const calcLeft = () => {
            if (window.innerWidth > 645) return;

            const isMobile = judgeMobile();
            const width = window.innerWidth - (isMobile ? 20 : 36) - standard;
            const sub = width / 4;

            setLeft(sub);
        };

        calcLeft();

        window.addEventListener("resize", calcLeft);

        return () => {
            window.removeEventListener("resize", calcLeft);
        };
    }, []);

    return (
        <div className={styles["selected-arcana-list"]}>
            {new Array(5).fill(-1).map((_, index) => {
                const id = deck.arcanaIds[index];
                const arcana = arcanaEntities[id];

                return (
                    <div className={styles["selected"]} style={{ left: `${left * index}px` }} key={v4()} onClick={() => setArcana(arcana)}>
                        {arcana && (
                            <div className={styles["mini-arcana"]}>
                                <img src={`${process.env.PUBLIC_URL}/images/cards/${getImageFileName(arcana.name["ko"])}.webp`} />
                                <div className={styles["top-overlay"]}>
                                    <span className={`${styles["rarity-badge"]} ${styles[arcana.rarity]}`}>{arcana.rarity}</span>
                                    <span className={styles["status"]}>
                                        <img src={`${process.env.PUBLIC_URL}/images/icon/journey_status/${arcana.mainStat["ko"]}.webp`} />
                                    </span>
                                </div>
                            </div>
                        )}
                        {!arcana && <i className="fi fi-sr-plus-small" />}
                    </div>
                );
            })}
            {/* <div style={{ color: "black", position: "absolute", top: "-50px" }}>{String(judgeMobile())}</div> */}
        </div>
    );
}
