import React, { useEffect, useMemo, useState } from "react";
import styles from "./wallpaper.module.css";
import { useSelector } from "react-redux";
import StarContainer from "../../components/star-container/star-container";
import Footer from "../../components/footer/footer";
import Header from "../../components/header/header";
import ScrollUpButton from "../../components/buttons/scroll-up-button/scroll-up-button";
import bgOrigin from "../../data/bg_images.json";
import getImageFileName from "../../functions/getImageFileName";
import { getUIText } from "../../translation";

const TAB_OBJECT = {
    ALL: { type: "ALL", name: "전체" },
    REGION: { type: "REGION", name: "지역", tabs: [] },
    PLACE: { type: "PLACE", name: "장소", tabs: [] },
    CHAR: { type: "CHAR", name: "캐릭터", tabs: [] },
    STORY: { type: "STORY", name: "스토리", tabs: [] },
    ETC: { type: "ETC", name: "기타", tabs: [] },
};

const REGIONS = ["NOA", "AGANON", "FLORA", "KALAID"];
const PLACE = ["CUBE", "STELLA_ARCHIVE", "PLAZA", "CORRIDOR", "FOREST", "HOTEL", "CANDLE_SQUARE"];
const STORY = ["MAIN", "EVENT", "JOURNEY", "CORRIDOR", "FOREST", "HOTEL", "CANDLE_SQUARE"];

export default function Wallpaper() {
    const theme = useSelector((state) => state.theme.value);
    const lang = useSelector((state) => state.lang.value);

    const subjectTabs = useMemo(() => {
        bgOrigin.forEach((e) => {
            e.tags.forEach((tag) => {
                if (REGIONS.includes(tag.type)) {
                    const found = TAB_OBJECT.REGION.tabs.find((r) => r.type === tag.type);

                    if (!found) TAB_OBJECT.REGION.tabs.push(tag);
                } else if (PLACE.includes(tag.type)) {
                    const found = TAB_OBJECT.PLACE.tabs.find((r) => r.type === tag.type);

                    if (!found) TAB_OBJECT.PLACE.tabs.push(tag);
                } else if (STORY.includes(tag.type)) {
                    const found = TAB_OBJECT.STORY.tabs.find((r) => r.type === tag.type);

                    if (!found) TAB_OBJECT.STORY.tabs.push(tag);
                } else if (tag.name.ko.includes("(")) {
                    const found = TAB_OBJECT.CHAR.tabs.find((r) => r.type === tag.type);

                    if (!found) TAB_OBJECT.CHAR.tabs.push(tag);
                } else {
                    const found = TAB_OBJECT.ETC.tabs.find((r) => r.type === tag.type);

                    if (!found) TAB_OBJECT.ETC.tabs.push(tag);
                }
            });
        });

        return TAB_OBJECT;
    }, []);
    const [selectedSubjectTab, setSelectedSubjectTab] = useState(subjectTabs.ALL);
    const [selectedSubTab, setSelectedSubTab] = useState(null);

    const [isDownloading, setIsDownloading] = useState(false);

    useEffect(() => {
        if (selectedSubjectTab.type === "ALL") {
            setSelectedSubTab(null);
        } else {
            setSelectedSubTab(selectedSubjectTab.tabs[0]);
        }
    }, [selectedSubjectTab]);

    const filteredList = useMemo(() => {
        return bgOrigin.filter((e) => {
            if (selectedSubjectTab.type === "ALL") return true;

            let hasTag = false;
            e.tags.forEach((tag) => {
                if (tag.type === selectedSubTab?.type) hasTag = true;
            });

            return hasTag;
        });
    }, [selectedSubjectTab, selectedSubTab]);

    const downloadImage = (wallpaper) => {
        setIsDownloading(true);

        try {
            const link = document.createElement("a");
            link.download = `${getImageFileName(wallpaper.tags.map((e) => e.name).join("_"))}.png`;
            link.href = `${process.env.PUBLIC_URL}/images/illust/bg/download/${wallpaper.download}`;
            link.click();
        } finally {
            setIsDownloading(false);
        }
    };

    return (
        <div id="container" data-theme={theme} data-lang={lang}>
            {theme === "dark" && <StarContainer />}
            <Header title={getUIText(lang, "header.title.wallpaper")} />
            <div className={styles["wallpaper-container"]}>
                <div className={styles["tabs"]}>
                    {Object.keys(subjectTabs).map((tabType) => {
                        return (
                            <button
                                className={`${styles["tab"]} ${selectedSubjectTab.type === tabType ? `${styles["active"]}` : ""}`}
                                onClick={() => setSelectedSubjectTab(subjectTabs[tabType])}
                            >
                                {lang === "ko" ? subjectTabs[tabType].name : subjectTabs[tabType].type}
                            </button>
                        );
                    })}
                </div>
                {selectedSubjectTab.tabs && (
                    <div className={styles["tabs"]}>
                        {selectedSubjectTab.tabs.map((tab) => {
                            return (
                                <button
                                    className={`${styles["tab"]} ${selectedSubTab?.type === tab.type ? `${styles["active"]}` : ""}`}
                                    onClick={() => setSelectedSubTab(tab)}
                                >
                                    {tab.name[lang]}
                                </button>
                            );
                        })}
                    </div>
                )}
                <div className={styles["wallpapers"]}>
                    {filteredList.map((wallpaper) => {
                        const origin = wallpaper.download.substring(0, wallpaper.download.lastIndexOf("."));
                        return (
                            <div className={styles["wallpaper"]}>
                                <img src={`${process.env.PUBLIC_URL}/images/illust/bg/${origin}.webp`} />
                                <div className={styles["wallpaper-info"]}>
                                    <div className={styles["size"]}>
                                        {wallpaper.size.width}x{wallpaper.size.height}
                                    </div>
                                </div>
                                <div className={styles["tags"]}>
                                    {wallpaper.tags.map((tag) => {
                                        return <div className={styles["tag"]}>#{tag.name[lang]}</div>;
                                    })}
                                </div>
                                <button
                                    type="button"
                                    className={styles["download"]}
                                    disabled={isDownloading}
                                    onClick={() => downloadImage(wallpaper)}
                                >
                                    {getUIText(lang, "wallpaper.download")}
                                </button>
                            </div>
                        );
                    })}
                </div>
            </div>

            <ScrollUpButton />
            <Footer />
        </div>
    );
}
