import React, { useEffect, useMemo, useRef, useState } from "react";
import styles from "./audio.module.css";
import { UI_TEXT } from "../../constants";
import { getUIText } from "../../translation";

export default function Audio({ lang, audio, playing, setPlaying, volume, isBackground = false }) {
    const [src, setSrc] = useState();
    const audioRef = useRef();

    useEffect(() => {
        import(`../../assets/bgm/${audio.filename}`).then((url) => {
            audioRef.current.volume = volume || 0.7;
            setSrc(url.default);
        });
    }, []);

    useEffect(() => {
        if (audio.music_name !== playing?.music_name) {
            audioRef.current.pause();
        }
    }, [playing]);

    useEffect(() => {
        audioRef.current.volume = volume;
    }, [volume]);

    useEffect(() => {
        audioRef.current;
    }, [audioRef.current]);

    const places = audio.places?.map((e) => e[lang]).join(" | ") ?? "";

    const audioComponenet = useMemo(() => {
        return (
            <audio
                ref={audioRef}
                src={src}
                preload={isBackground ? "auto" : "none"}
                controls
                controlsList="nodownload nofullscreen noremoteplayback"
                autoPlay={isBackground}
                loop={isBackground}
                // muted={isBackground}
                onCanPlay={(e) => {
                    // audioRef.current.click();
                    audioRef.current.play();
                    audioRef.current.muted = false;
                }}
                onPlay={() => {
                    if (!isBackground) setPlaying(audio);
                }}
            />
        );
    }, [src]);

    return (
        <div className={`${styles["audio-wrapper"]} ${isBackground ? styles["hide"] : ""}`}>
            <div className={styles["summary"]}>
                <div className={styles["music-name"]}>
                    {getUIText(lang, "music.audio.music.name")} : {audio.music_name[lang]}
                </div>
                <div className={styles["music-name"]} title={places}>
                    {audio.places ? `${getUIText(lang, "music.audio.place")} : ${places}` : ""}
                </div>
            </div>
            {audioComponenet}
        </div>
    );
}
