import React, { useState } from "react";
import styles from "./deck-summary.module.css";
import { useSelector } from "react-redux";
import { v4 } from "uuid";
// import { calculateStats } from "../../store/reducers/list/deckList";
import {
    selectArcanaEntities,
    selectSelectedDeckArcanaIdsIncludesPotential,
    selectSelectedDeckStats,
} from "../../store/selectors/arcanaSelectors";
import { UI_TEXT } from "../../constants";
import { getUIText } from "../../translation";

const levelFlags = ["level_35", "level_50"];

export default function DeckSummary({ lang }) {
    const arcanaIdsIncludesPotential = useSelector((state) => selectSelectedDeckArcanaIdsIncludesPotential(state));
    const stats = useSelector((state) => selectSelectedDeckStats(state));

    const arcanaEntities = useSelector((state) => selectArcanaEntities(state));

    const [isFold, setIsFold] = useState(true);
    const [levelFlag, setLevelFlag] = useState(localStorage.getItem("level_flag") || "level_50");

    const changeLevelFlag = (flag) => {
        if (!levelFlags.includes(flag)) return;

        localStorage.setItem("level_flag", flag);
        setLevelFlag(flag);
    };

    return (
        <div className={`${styles["deck-summary"]} ${isFold ? "" : `${styles["active"]}`}`}>
            <button type="button" className={styles["toggle-summary-button"]} onClick={() => setIsFold(!isFold)}>
                {getUIText(lang, "deck.summary.overview")}
                <span className={styles["triangle"]}>▼</span>
            </button>
            <div className={styles["deck-summary-wrapper"]}>
                <div className={styles["potentials"]}>
                    <div className={styles["title"]}>{getUIText(lang, "deck.summary.spPotential")}</div>
                    {arcanaIdsIncludesPotential.map((id) => {
                        const arcana = arcanaEntities[id];
                        return (
                            <div className={styles["potential"]} key={v4()}>
                                <div className={styles["title"]}>{arcana.spPotential.name[lang]}</div>
                                <div className={styles["desc"]}>{arcana.spPotential.desc[lang]}</div>
                            </div>
                        );
                    })}
                </div>
                <div className={styles["status-wrapper"]}>
                    <div className={styles["status-title-wrapper"]}>
                        <div className={styles["title"]}>{getUIText(lang, "deck.summary.totalStatus")}</div>
                        <div className={styles["level-buttons"]}>
                            <button
                                type="button"
                                className={`${levelFlag === levelFlags[0] ? `${styles["active"]}` : ""}`}
                                onClick={() => changeLevelFlag(levelFlags[0])}
                            >
                                Lv.35
                            </button>
                            <button
                                type="button"
                                className={`${levelFlag === levelFlags[1] ? `${styles["active"]}` : ""}`}
                                onClick={() => changeLevelFlag(levelFlags[1])}
                            >
                                Lv.50
                            </button>
                        </div>
                    </div>
                    <div className={styles["acc-journey-status"]}>
                        {stats &&
                            stats.acc.map((stat) => {
                                return (
                                    <div className={styles["journey-status"]} key={v4()}>
                                        <span className={styles["stat-name"]}>{stat.type[lang]}</span>
                                        <span className={styles["stat-value"]}>{stat[`${levelFlag}_string`]}</span>
                                    </div>
                                );
                            })}
                    </div>
                    <div className={styles["additional-journey-status"]}>
                        {stats &&
                            stats.additional.map((statObj) => {
                                return (
                                    <div className={styles["additional-status"]} key={v4()}>
                                        <div className={styles["title"]}>{statObj.name[lang]}</div>
                                        {statObj.list.map((stat) => {
                                            return (
                                                <div className={`${styles["journey-status"]} ${styles["desc"]}`} key={v4()}>
                                                    <span className={styles["stat-name"]}>{stat.type[lang]}</span>
                                                    <span className={styles["stat-value"]}>{stat[`${levelFlag}_string`]}</span>
                                                </div>
                                            );
                                        })}
                                    </div>
                                );
                            })}
                    </div>
                </div>
            </div>
        </div>
    );
}
