import React from "react";
import styles from "./description-wrapper.module.css";
import { v4 } from "uuid";
import { useSelector } from "react-redux";
import { selectJourneyEntities } from "../../store/selectors/journeySelectors";
import { JOURNEY_EVENT_TYPE_ENG, OCCUR_TYPE_ENG, SCHEDULE_CONTENT_ENG } from "../../constants";
// import { getJourneyEventByName } from "../../functions/getJourneyFunctions";

export default function DescriptionWrapper({ lang, desc, setSelected }) {
    const journeyEntities = useSelector((state) => selectJourneyEntities(state));

    return (
        <div className={styles["description-wrapper"]} key={v4()}>
            <div className={styles["description"]}>
                <div
                    className={`${styles["badge"]} ${styles["occur-type"]} ${
                        desc.occur_type === "확률" ? `${styles["per"]}` : desc.occur_type === "랜덤" ? `${styles["random"]}` : ""
                    }`}
                >
                    {lang === "ko" ? desc.occur_type : OCCUR_TYPE_ENG[desc.occur_type]}
                </div>
                <div
                    className={`${styles["badge"]} ${styles["type"]} ${
                        desc.type === "아르카나" ? `${styles["arcana"]}` : desc.type === "여정" ? `${styles["journey"]}` : ""
                    }`}
                >
                    {lang === "ko" ? desc.type : JOURNEY_EVENT_TYPE_ENG[desc.type]}
                </div>
                <div className={styles["contents"]}>
                    {desc.contents.map((content) => {
                        const journey = journeyEntities[content];
                        let name;
                        if (journey && journey.name) name = journey.name[lang];
                        if (!name) name = lang === "ko" ? content : SCHEDULE_CONTENT_ENG[content];

                        return (
                            <button
                                type="button"
                                className={`${styles["badge"]} ${styles["content-name-button"]}`}
                                key={v4()}
                                onClick={() => {
                                    if (!journey && content !== "날씨" && content !== "아르카나 이벤트") return;
                                    else if (content === "날씨" || content === "아르카나 이벤트")
                                        setSelected({ content: content, desc: desc });
                                    else setSelected({ content: journey, desc: desc });
                                }}
                            >
                                {(journey || content === "날씨" || content === "아르카나 이벤트") && <i className="fi fi-rs-search" />}
                                {name}
                            </button>
                        );
                    })}
                </div>
            </div>
        </div>
    );
}
