import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/journeys.json";
import journeyItems from "../../../data/journey_items.json";
import potentials from "../../../data/potentials.json";
import statPotentials from "../../../data/stat_potentials.json";
import buffs from "../../../data/journey_buffs.json";
import FILTERS from "../../../data/filter_config.json";
import { getJourneyTimeString } from "../../../functions/stringFunctions";
import { CHOICE_CONDITION_TYPE, JOURNEY_REWARD_TYPE } from "../../../constants";

const lang = localStorage.getItem("language") || "ko";

const getMonthPriority = (monthStr) => {
    const month = parseInt(monthStr.replace("월", ""));
    if (month >= 3) return month - 3;
    return month + 9;
};

const getPeriodPriority = (periodStr) => {
    if (periodStr === "초순") return 0;
    if (periodStr === "중순") return 1;
    if (periodStr === "하순") return 2;
    return 3;
};

const sortJourneys = (a, b) => {
    const aObj = originData[a][0];
    const bObj = originData[b][0];

    const aTime = aObj.times?.length > 0 ? aObj.times[0] : null;
    const bTime = bObj.times?.length > 0 ? bObj.times[0] : null;

    if (!aTime && !bTime) return 0;
    if (!aTime) return 1;
    if (!bTime) return -1;

    const [aMonth, aPeriod] = aTime.split(" ");
    const [bMonth, bPeriod] = bTime.split(" ");

    const aMonthP = getMonthPriority(aMonth);
    const bMonthP = getMonthPriority(bMonth);

    if (aMonthP !== bMonthP) return aMonthP - bMonthP;

    return getPeriodPriority(aPeriod) - getPeriodPriority(bPeriod);
};

const normalizeJourneys = (originData) => {
    const entities = {};
    const ids = [];

    // 성능 최적화: Map으로 미리 인덱싱하여 O(1) 조회
    const itemMap = new Map(journeyItems.map((item) => [item.id, item]));
    const potentialMap = new Map(potentials.map((p) => [p.id, p]));
    const statPotentialMap = new Map(statPotentials.map((sp) => [sp.id, sp]));
    const buffMap = new Map(buffs.map((b) => [b.id, b]));

    Object.entries(originData).forEach(([journeyName, journeys]) => {
        const base = journeys[0];

        const parts = [];
        const parts_ENG = [];

        parts.push(base.name.ko);
        parts_ENG.push(base.name.en);
        if (base.times) {
            base.times.forEach((time) => {
                parts.push(time);
                parts_ENG.push(getJourneyTimeString("en", time));
            });
        }

        const variants = journeys.map((journey) => {
            journey.choices.forEach((choice) => {
                if (choice.name !== "") {
                    parts.push(choice.name.ko);
                    parts_ENG.push(choice.name.en);
                }

                if (choice.condition) {
                    if (choice.condition.type.includes("ITEM")) {
                        const item = itemMap.get(Number(choice.condition.target));

                        if (item) {
                            parts.push(item.name.ko);
                            parts_ENG.push(item.name.en);
                            choice.condition.item = item;
                        }
                    } else {
                        const value = choice.condition.value > 0 ? `+${choice.condition.value}` : choice.condition.value;
                        parts.push(CHOICE_CONDITION_TYPE[choice.condition.type].ko);
                        parts.push(value);
                        parts_ENG.push(CHOICE_CONDITION_TYPE[choice.condition.type].en);
                        parts_ENG.push(value);
                    }
                }

                [...choice.success_rewards, ...choice.failure_rewards].forEach((rewards) => {
                    rewards.forEach((reward) => {
                        let obj;

                        if (reward.type === "RT_JOURNEY_ITEM") {
                            obj = itemMap.get(reward.reward_id);
                        } else if (reward.type === "RT_SE_POTEN") {
                            obj = potentialMap.get(reward.reward_id);
                        } else if (reward.type === "RT_STAT_POTEN") {
                            obj = statPotentialMap.get(reward.reward_id);
                        } else if (reward.type === "RT_JOURNEY_BUFF") {
                            obj = buffMap.get(reward.reward_id);
                        }

                        if (obj) {
                            parts.push(obj.name.ko);
                            parts_ENG.push(obj.name.en);
                            reward.targetObj = obj;
                        } else {
                            parts.push(JOURNEY_REWARD_TYPE[reward.type].ko);
                            parts_ENG.push(JOURNEY_REWARD_TYPE[reward.type].en);
                        }
                    });
                });
            });

            let battleNames = journey.battle_names ?? null;
            if (battleNames && battleNames.length > 1) {
                const common = battleNames[0].ko.replace(" Ⅰ", "");
                const common_ENG = battleNames[0].en.replace(" Ⅰ", "");
                battleNames = battleNames.map((name, index) => {
                    if (index > 0) return { ko: name.ko.replace(common, ""), en: name.en.replace(common_ENG, "") };
                    return name;
                });
            }

            let difficulties = journey.difficulties ?? null;
            // if (difficulties) {
            //     difficulties = difficulties.map((diff) => {
            //         console.log(diff);
            //         if (diff === "이지") return { kor: "이지", eng: "easy" };
            //         if (diff === "노말") return { kor: "노말", eng: "normal" };
            //         if (diff === "하드") return { kor: "하드", eng: "hard" };
            //         return null;
            //     });
            // }

            return {
                difficulties: difficulties,
                battleNames: battleNames,
                choices: journey.choices,
            };
        });

        entities[journeyName] = {
            id: base.id,
            name: base.name,
            type: base.type,
            times: base.times ?? [],
            variants: variants,
            searchText: parts.join(" "),
            searchText_ENG: parts_ENG.join(" "),
        };

        ids.push(journeyName);
    });

    ids.sort(sortJourneys);

    return { entities, ids };
};

const normalized = normalizeJourneys(originData);

const journeySlice = createSlice({
    name: "journeys",
    initialState: {
        entities: normalized.entities,
        ids: normalized.ids,
        filter: {
            tab: FILTERS.JOURNEY_GROUP[0],
            difficulty: FILTERS.JOURNEY_DIFFICULTY[0],
        },
    },
    reducers: {
        changeTab: (state, action) => {
            state.filter.tab = action.payload;
        },
        changeDifficulty: (state, action) => {
            state.filter.difficulty = action.payload.obj;
        },
    },
});

export const { changeTab, changeDifficulty } = journeySlice.actions;
export default journeySlice.reducer;
