import { createSelector } from "@reduxjs/toolkit";
import originSaviorData from "../../data/saviors.json";
import originArcanaData from "../../data/arcanas.json";
import GACHA_DATA from "../../data/gacha.json";
import { getSaviorById, getSaviorByNameTitle } from "../../functions/getSaviorFunctions";
import { getArcanaById } from "../../functions/getArcanaFunctions";

const COSMIC_ATTR = ["질서", "혼돈"];

const selectLang = (state) => state.lang;

export const selectGachaState = (state) => state.gacha;

export const selectSaviorGacha = (state) => selectGachaState(state).savior;

export const selectArcanaGacha = (state) => selectGachaState(state).arcana;

export const selectSnipeGacha = (state) => selectGachaState(state).snipe;

export const selectIsPickup = (state) => selectGachaState(state).isPickup;

export const selectPickupHasCosmic = (state) => selectGachaState(state).pickupHasCosmic;

export const selectSaviorPickupType = (state) => selectGachaState(state).saviorPickupType;

export const selectSaviorCommonTargetList = createSelector([selectLang], (lang) => {
    const locale = lang === "ko" ? "ko-KR" : "en-US";

    return originSaviorData
        .filter((savior) => !GACHA_DATA.NOT_IN_SAVIOR_COMMONS.includes(savior.id) && !GACHA_DATA.SAVIOR_PICKUPS.includes(savior.id))
        .sort((a, b) => a.name[lang.value].localeCompare(b.name[lang.value], locale))
        .map((savior) => `${savior.name[lang.value]}(${savior.title[lang.value]})`);
});

export const selectSaviorPickupTargetList = createSelector([selectLang], (lang) => {
    return GACHA_DATA.SAVIOR_PICKUPS.map((id) => {
        const savior = getSaviorById(id);
        return `${savior.name[lang.value]}(${savior.title[lang.value]})`;
    });
});

export const selectArcanaCommonTargetList = createSelector([selectLang], (lang) => {
    return originArcanaData
        .filter((arcana) => !GACHA_DATA.NOT_IN_ARCANA_COMMONS.includes(arcana.id) && !GACHA_DATA.ARCANA_PICKUPS.includes(arcana.id))
        .map((arcana) => arcana.name[lang.value]);
});

export const selectArcanaPickupTargetList = createSelector([selectLang], (lang) => {
    return GACHA_DATA.ARCANA_PICKUPS.map((id) => getArcanaById(id).name[lang.value]);
});

export const selectSnipeTargetList = createSelector(
    [
        selectSnipeGacha,
        selectIsPickup,
        selectSaviorPickupTargetList,
        selectArcanaPickupTargetList,
        selectSaviorCommonTargetList,
        selectArcanaCommonTargetList,
    ],
    (snipe, isPickup, saviorPickupTargetList, arcanaPickupTargetList, saviorCommonTargetList, arcanaCommonTargetList) => {
        if (snipe.type.value === "savior") {
            return isPickup ? saviorPickupTargetList : saviorCommonTargetList;
        } else {
            return isPickup ? arcanaPickupTargetList : arcanaCommonTargetList;
        }
    },
);

export const selectCurrentSnipeTarget = createSelector([selectSnipeGacha, selectSnipeTargetList], (snipe, targetList) => {
    if (!snipe.target && targetList.length > 0) {
        return targetList[0];
    }
    return snipe.target || "";
});

export const selectSnipeTargetCosmicType = createSelector([selectSnipeGacha], (snipe) => {
    if (snipe.type.value === "savior") {
        const target = getSaviorByNameTitle(snipe.target);
        return target && COSMIC_ATTR.includes(target.attr) ? "cosmic" : "not_cosmic";
    }
    return "not_cosmic";
});
