import React from "react";
import styles from "./portrait-with-name.module.css";
import { SAVIOR_ATTRIBUTE, SAVIOR_CLASS } from "../../../constants";

export default function PortraitWithName({ lang, savior, setIsActive, setSelected }) {
    const eng = savior.attr.replace("NUAT_", "").toLowerCase();

    const selectSavior = (savior) => {
        setSelected(savior);
        setIsActive(true);
    };

    return (
        <div className={styles["savior"]} onClick={() => selectSavior(savior)}>
            <div className={`${styles["portrait"]} ${styles[`${eng}`]}`}>
                <img
                    alt={savior.name[lang]}
                    src={`${process.env.PUBLIC_URL}/images/icon/portrait/${savior.name["ko"]}(${savior.title["ko"]}).webp`}
                />
                <div className={styles["class-overlay"]}>
                    <img
                        src={`${process.env.PUBLIC_URL}/images/icon/portrait/${SAVIOR_ATTRIBUTE[savior.attr]["ko"]}.webp`}
                        className={styles["attr"]}
                    />
                    <img
                        src={`${process.env.PUBLIC_URL}/images/icon/portrait/${SAVIOR_CLASS[savior.class]["ko"]}.webp`}
                        className={styles["class"]}
                    />
                </div>
            </div>
            <div className={styles["name-wrapper"]}>
                <div className={styles["name"]}>{savior.name[lang]}</div>
                <div className={styles["title"]}>{savior.title[lang]}</div>
            </div>
        </div>
    );
}
