import React, { useEffect, useMemo, useRef, useState } from "react";
import styles from "./preset-export-modal.module.css";
import FilterSelect from "../../filter-select/filter-select";
import {
    decodeArchivePreset,
    decodeCharPreset,
    decodeEquipPreset,
    encodeArchivePreset,
    encodeCharPreset,
    encodeEquipPreset,
} from "../../../functions/bitFunctions";
import { createPortal } from "react-dom";
import { getUIText } from "../../../translation";

const TABS = [
    { ko: "내보내기", en: "Export" },
    { ko: "불러오기", en: "import" },
];

export default function PresetExportModal({ lang, isActive, setIsActive, saviorPresets, archivePresets, equipPresets, setPresets }) {
    const [selectedTab, setSelectedTab] = useState(TABS[0]);

    const saviorPresetFilterList = useMemo(() => {
        const result = [
            {
                name: getUIText(lang, "simulator.modal.export.filter.savior.title"),
                value: 0,
            },
        ];
        if (!saviorPresets) return result;

        result.push(
            ...saviorPresets.map((e) => {
                return {
                    ...e,
                    value: `${e.charId}_${e.slot}`,
                };
            }),
        );

        return result;
    }, [saviorPresets]);
    const [selectedCharPreset, setSelectedCharPreset] = useState(saviorPresetFilterList ? saviorPresetFilterList[0] : null);
    const [targetCharPreset, setTargetCharPreset] = useState(saviorPresetFilterList ? saviorPresetFilterList[0] : null);

    const archivePresetFilterList = useMemo(() => {
        const result = [
            {
                name: getUIText(lang, "simulator.modal.export.filter.archive.title"),
                value: 0,
            },
        ];
        if (!archivePresets) return result;

        result.push(
            ...archivePresets.map((e) => {
                return {
                    ...e,
                    value: `${e.charId}_${e.slot}`,
                };
            }),
        );

        return result;
    }, [archivePresets]);
    const [selectedArchivePreset, setSelectedArchivePreset] = useState(archivePresetFilterList ? archivePresetFilterList[0] : null);
    const [targetArchivePreset, setTargetArchivePreset] = useState(archivePresetFilterList ? archivePresetFilterList[0] : null);

    const equipPresetFilterList = useMemo(() => {
        const result = [
            {
                name: getUIText(lang, "simulator.modal.export.filter.equip.title"),
                value: 0,
            },
        ];
        if (!equipPresets) return result;

        result.push(
            ...equipPresets.map((e) => {
                return {
                    ...e,
                    value: `${e.charId}_${e.slot}`,
                };
            }),
        );

        return result;
    }, [equipPresets]);
    const [selectedEquipPreset, setSelectedEquipPreset] = useState(equipPresetFilterList ? equipPresetFilterList[0] : null);
    const [targetEquipPreset, setTargetEquipPreset] = useState(equipPresetFilterList ? equipPresetFilterList[0] : null);

    const textareaRef = useRef(null);
    const [code, setCode] = useState(null);
    const [pastedCode, setPastedCode] = useState("");

    const [confirmProgress, setConfirmProgress] = useState(false);
    const [copyFlag, setCopyFlag] = useState(null);
    const [pasteFlag, setPasteFlag] = useState(null);
    const [pasteIndicator, setPasteIndicator] = useState({
        savior: false,
        archive: false,
        equip: false,
    });

    const createPresetCode = () => {
        if (!selectedCharPreset.value && !selectedArchivePreset.value && !selectedEquipPreset.value) return;

        let char;
        let charString;
        let archive;
        let archiveString;
        let equip;
        let equipString;

        const codes = [];

        if (selectedCharPreset.value !== 0) {
            char = encodeCharPreset(selectedCharPreset);
            charString = `c1.${selectedCharPreset.name}.${char}`;
            codes.push(charString);
            // let decoded = decodeCharPreset(char, "에데 1");
        }
        if (selectedArchivePreset.value !== 0) {
            archive = encodeArchivePreset(selectedArchivePreset);
            archiveString = `a1.${selectedArchivePreset.name}.${archive}`;
            codes.push(archiveString);
            // let decoded = decodeArchivePreset(archive, "에데 1");
        }
        if (selectedEquipPreset.value !== 0) {
            equip = encodeEquipPreset(selectedEquipPreset);
            equipString = `e1.${selectedEquipPreset.name}.${equip}`;
            codes.push(equipString);
            // let decoded = decodeEquipPreset(equip, "에데 1");
        }

        setCode(codes.join("\n"));
    };

    const copyToClipboard = () => {
        navigator.clipboard
            .writeText(code)
            .then(() => {
                setCopyFlag(true);

                setTimeout(() => {
                    setCopyFlag(null);
                }, 2000);
            })
            .catch((e) => {
                setCopyFlag(false);

                setTimeout(() => {
                    setCopyFlag(null);
                }, 2000);
            });
    };

    const pasteFromClipboard = () => {
        navigator.clipboard
            .readText()
            .then((text) => {
                setPastedCode(text);
                setPasteFlag(true);

                setTimeout(() => {
                    setPasteFlag(null);
                }, 2000);
            })
            .catch((e) => {
                setPasteFlag(false);

                setTimeout(() => {
                    setPasteFlag(null);
                }, 2000);
            });
    };

    useEffect(() => {
        if (!textareaRef.current) return;

        if (!pastedCode) {
            textareaRef.current.style.height = `auto`;
        } else {
            textareaRef.current.style.height = `auto`;
            textareaRef.current.style.height = `${textareaRef.current.scrollHeight}px`;

            const obj = {
                savior: false,
                archive: false,
                equip: false,
            };

            pastedCode.split("\n").map((line) => {
                const code = line.trim();

                if (code.startsWith("c1")) obj.savior = code;
                if (code.startsWith("a1")) obj.archive = code;
                if (code.startsWith("e1")) obj.equip = code;
            });

            setPasteIndicator(obj);
        }
    }, [pastedCode]);

    const openConfirmModal = () => {
        if (targetCharPreset.value !== 0 || targetArchivePreset.value !== 0 || targetEquipPreset.value !== 0) {
            setConfirmProgress(true);
        }
    };

    const applyPresets = () => {
        let charPreset;
        let archivePreset;
        let equipPreset;

        if (pasteIndicator.savior && targetCharPreset.value !== 0) {
            const [type, name, code] = pasteIndicator.savior.split(".");

            if (type === "c1") {
                charPreset = decodeCharPreset(code, name);

                charPreset.slot = targetCharPreset.slot;
            }
        }
        if (pasteIndicator.archive && targetArchivePreset.value !== 0) {
            const [type, name, code] = pasteIndicator.archive.split(".");

            if (type === "a1") {
                archivePreset = decodeArchivePreset(code, name);

                archivePreset.slot = targetArchivePreset.slot;
            }
        }
        if (pasteIndicator.equip && targetEquipPreset.value !== 0) {
            const [type, name, code] = pasteIndicator.equip.split(".");

            if (type === "e1") {
                equipPreset = decodeEquipPreset(code, name);

                equipPreset.slot = targetEquipPreset.slot;
            }
        }

        if (charPreset || archivePreset || equipPreset) {
            setPresets(charPreset, archivePreset, equipPreset).then((e) => {
                setConfirmProgress(false);
                setIsActive(false);
                setCode(null);
                setPastedCode("");
                setPasteIndicator({
                    savior: false,
                    archive: false,
                    equip: false,
                });
                setTargetCharPreset(saviorPresetFilterList[0]);
                setTargetArchivePreset(archivePresetFilterList[0]);
                setTargetEquipPreset(equipPresetFilterList[0]);
                setSelectedCharPreset(saviorPresetFilterList[0]);
                setSelectedArchivePreset(archivePresetFilterList[0]);
                setSelectedEquipPreset(equipPresetFilterList[0]);
            });
        }
    };

    return (
        <div
            className={`modal items overflow ${isActive ? "active" : ""}`}
            // onClick={(e) => {
            //     if (e.target.classList.contains("modal")) {
            //         setEditingTactics(null);
            //     }
            // }}
        >
            <div className="window">
                <button className="close-button" onClick={() => setIsActive(!isActive)}>
                    <i className="fi fi-sr-x" />
                </button>
                <div className={styles["preset-export-container"]}>
                    <div className={styles["title"]}>
                        {getUIText(lang, "simulator.modal.export.title")} {selectedTab[lang]}
                    </div>
                    <div className={styles["tabs"]}>
                        {TABS.map((tab) => (
                            <button
                                type="button"
                                className={`${styles["tab"]} ${tab.ko === selectedTab.ko ? `${styles["active"]}` : ""}`}
                                key={`tab_button_${tab[lang]}`}
                                onClick={() => setSelectedTab(tab)}
                            >
                                {tab[lang]}
                            </button>
                        ))}
                    </div>
                    {selectedTab.ko === TABS[0].ko && (
                        <div className={styles["export-container"]}>
                            {/* <span>시설 레벨</span> */}
                            {/* <input
                                type="text"
                                value={editing.facility}
                                onChange={(e) => changeLevel("facility", null, e.target.value)}
                                onBlur={(e) => ensureLevel("facility", null, e.target.value)}
                            /> */}
                            <FilterSelect
                                id={"savior_preset_selector"}
                                list={saviorPresetFilterList}
                                selected={selectedCharPreset}
                                changeFilter={(obj) => setSelectedCharPreset(obj)}
                                forceWidth={"100%"}
                                forceSmallPadding={true}
                                isUseDispatch={false}
                            />
                            <FilterSelect
                                id={"archive_preset_selector"}
                                list={archivePresetFilterList}
                                selected={selectedArchivePreset}
                                changeFilter={(obj) => setSelectedArchivePreset(obj)}
                                forceWidth={"100%"}
                                forceSmallPadding={true}
                                isUseDispatch={false}
                            />
                            <FilterSelect
                                id={"equip_preset_selector"}
                                list={equipPresetFilterList}
                                selected={selectedEquipPreset}
                                changeFilter={(obj) => setSelectedEquipPreset(obj)}
                                forceWidth={"100%"}
                                forceSmallPadding={true}
                                isUseDispatch={false}
                            />
                            <div className={styles["buttons"]}>
                                <button type="button" className={styles["submit-button"]} onClick={() => createPresetCode()}>
                                    {getUIText(lang, "simulator.modal.export.buttons.export")}
                                </button>
                            </div>
                            <div className={styles["code-container"]}>
                                <div
                                    className={styles["code"]}
                                    dangerouslySetInnerHTML={{ __html: code?.replaceAll("\n", "<br />") }}
                                ></div>
                                <button
                                    type="button"
                                    className={`${styles["code-copy-button"]} ${copyFlag === true ? `${styles["success"]}` : copyFlag === false ? `${styles["fail"]}` : ""}`}
                                    onClick={copyToClipboard}
                                >
                                    <i className="fi fi-rr-copy" />
                                </button>
                            </div>
                        </div>
                    )}
                    {selectedTab === TABS[1] && (
                        <div className={styles["export-container"]}>
                            <div className={styles["code-container"]}>
                                <textarea
                                    ref={textareaRef}
                                    className={styles["code"]}
                                    value={pastedCode}
                                    onChange={(e) => setPastedCode(e.target.value)}
                                ></textarea>
                                <button
                                    type="button"
                                    className={`${styles["code-copy-button"]} ${pasteFlag === true ? `${styles["success"]}` : pasteFlag === false ? `${styles["fail"]}` : ""}`}
                                    onClick={pasteFromClipboard}
                                >
                                    <i className="fi fi-rr-paste" />
                                </button>
                            </div>
                            {Object.keys(pasteIndicator).map((flag) => {
                                if (!pasteIndicator[flag]) return;

                                let list;
                                let target;
                                let setter;
                                if (flag === "savior") {
                                    list = saviorPresetFilterList;
                                    target = targetCharPreset;
                                    setter = setTargetCharPreset;
                                } else if (flag === "archive") {
                                    list = archivePresetFilterList;
                                    target = targetArchivePreset;
                                    setter = setTargetArchivePreset;
                                } else if (flag === "equip") {
                                    list = equipPresetFilterList;
                                    target = targetEquipPreset;
                                    setter = setTargetEquipPreset;
                                }

                                return (
                                    <FilterSelect
                                        id={`${flag}_preset_selector`}
                                        list={list}
                                        selected={target}
                                        changeFilter={(obj) => setter(obj)}
                                        forceWidth={"100%"}
                                        forceSmallPadding={true}
                                        isUseDispatch={false}
                                        key={`${flag}_target_preset_selector`}
                                    />
                                );
                            })}
                            <div className={styles["buttons"]}>
                                <button type="button" className={styles["submit-button"]} onClick={() => openConfirmModal()}>
                                    {getUIText(lang, "simulator.modal.tactics.confirm")}
                                </button>
                                <button type="button" className={styles["cancel-button"]} onClick={() => setIsActive(!isActive)}>
                                    {getUIText(lang, "simulator.modal.tactics.cancel")}
                                </button>
                            </div>
                        </div>
                    )}
                </div>
                {confirmProgress &&
                    createPortal(
                        <div className={`modal fit ${confirmProgress ? `active` : ""}`}>
                            <div className="window">
                                <button
                                    className="close-button"
                                    onClick={(e) => {
                                        e.stopPropagation();
                                        setConfirmProgress(false);
                                    }}
                                >
                                    <i className="fi fi-sr-x" />
                                </button>
                                <div className={styles["preset-export-container"]}>
                                    <div className={styles["title"]}>{getUIText(lang, "simulator.modal.export.confirm.title")}</div>
                                    <div className={styles["desc"]}>
                                        <table>
                                            <tbody>
                                                <tr>
                                                    <td>{getUIText(lang, "simulator.modal.export.confirm.new")}</td>
                                                    <td>→</td>
                                                    <td>{getUIText(lang, "simulator.modal.export.confirm.before")}</td>
                                                </tr>
                                                {Object.keys(pasteIndicator).map((type) => {
                                                    if (!pasteIndicator[type]) return;

                                                    const [_, name, __] = pasteIndicator[type].split(".");
                                                    let target;

                                                    if (type === "savior") target = targetCharPreset;
                                                    else if (type === "archive") target = targetArchivePreset;
                                                    else if (type === "equip") target = targetEquipPreset;

                                                    return (
                                                        <tr key={`confirm_apply_preset_${type}`}>
                                                            <td>{name}</td>
                                                            <td>→</td>
                                                            {target && <td>{target.value === 0 ? "" : target.name}</td>}
                                                        </tr>
                                                    );
                                                })}
                                            </tbody>
                                        </table>
                                    </div>
                                    <div className={styles["buttons"]}>
                                        <button type="button" className={styles["submit-button"]} onClick={() => applyPresets()}>
                                            {getUIText(lang, "simulator.modal.tactics.confirm")}
                                        </button>
                                        <button type="button" className={styles["cancel-button"]} onClick={() => setConfirmProgress(false)}>
                                            {getUIText(lang, "simulator.modal.tactics.cancel")}
                                        </button>
                                    </div>
                                </div>
                            </div>
                        </div>,
                        document.getElementById("portal-root"),
                    )}
            </div>
        </div>
    );
}
