import React, { useMemo, useState } from "react";
import styles from "./music.module.css";
import { useSelector } from "react-redux";
import StarContainer from "../../components/star-container/star-container";
import Footer from "../../components/footer/footer";
import Header from "../../components/header/header";
import ScrollUpButton from "../../components/buttons/scroll-up-button/scroll-up-button";
import audios from "../../data/audios.json";
import Audio from "../../components/music/audio";
import VolumeSlider from "../../components/music/volume-slider";
import { getUIText } from "../../translation";

export default function Music() {
    const theme = useSelector((state) => state.theme.value);
    const lang = useSelector((state) => state.lang.value);

    const usedVolume = localStorage.getItem("volume");
    const [volume, setVolume] = useState(usedVolume ? Number(usedVolume) : 0.7);
    const [playing, setPlaying] = useState();

    const audioList = useMemo(() => audios, []);

    const changeVolume = (value) => {
        setVolume(value);
        localStorage.setItem("volume", value);
    };

    return (
        <div id="container" data-theme={theme} data-lang={lang}>
            {theme === "dark" && <StarContainer />}
            <Header title={getUIText(lang, "header.title.bgm")} />
            <div className={styles["music-container"]}>
                <VolumeSlider lang={lang} volume={volume} setVolume={changeVolume} />
                <div className={styles["warning"]}>{getUIText(lang, "music.warning")}</div>
                {audioList.map((audio) => {
                    return (
                        <Audio lang={lang} audio={audio} key={audio.filename} playing={playing} setPlaying={setPlaying} volume={volume} />
                    );
                })}
            </div>

            <ScrollUpButton />
            <Footer />
        </div>
    );
}
