import React, { useEffect, useState } from "react";
import styles from "./deck.module.css";
import StarContainer from "../../components/star-container/star-container";
import Header from "../../components/header/header";
import { useDispatch, useSelector } from "react-redux";
import ScrollUpButton from "../../components/buttons/scroll-up-button/scroll-up-button";
import Footer from "../../components/footer/footer";
// import { changeFilter, changeQuery, reset } from "../../store/reducers/list/arcanaList";
import SearchBox from "../../components/search-box/search-box";
import Card from "../../components/arcana/card";
import { v4 } from "uuid";
// import { toggleArcana } from "../../store/reducers/list/deckList";
import FilterSelect from "../../components/filter-select/filter-select";
import FILTERS from "../../data/filter_config.json";
import DeckChanger from "../../components/deck/deck-changer";
import SelectedArcanaList from "../../components/deck/selected-arcana-list";
import DeckSummary from "../../components/deck/deck-summary";
import { selectArcanaEntities, selectArcanaFilter, selectArcanaIdsNotInSelectedDeck } from "../../store/selectors/arcanaSelectors";
import { changeFilter } from "../../store/reducers/list/arcanaList";
import { toggleArcana } from "../../store/reducers/list/deckList";
import { getUIText } from "../../translation";

export default function Deck() {
    const theme = useSelector((state) => state.theme.value);
    const lang = useSelector((state) => state.lang.value);

    const [query, setQuery] = useState("");

    const arcanaIds = useSelector((state) => selectArcanaIdsNotInSelectedDeck(state, query));
    const arcanaEntities = useSelector((state) => selectArcanaEntities(state));
    const arcanaFilter = useSelector((state) => selectArcanaFilter(state));

    const dispatch = useDispatch();

    return (
        <div id="container" data-theme={theme} data-lang={lang}>
            {theme === "dark" && <StarContainer />}
            <Header title={getUIText(lang, "header.title.deck")} />

            <div className={styles["deck-container"]}>
                {/* TODO : deck changer */}
                <DeckChanger />

                {/* TODO : card list in deck */}
                <SelectedArcanaList lang={lang} setArcana={(arcana) => dispatch(toggleArcana(arcana))} />

                {/* TODO : deck summary foldable default: folded */}
                <DeckSummary lang={lang} />

                {/* TODO : card search box */}
                <div className={styles["search-boxes"]}>
                    <FilterSelect
                        id={"rarity"}
                        list={lang === "ko" ? FILTERS.ARCANA_RARITY : FILTERS.ARCANA_RARITY_ENG}
                        selected={arcanaFilter.rarity}
                        changeFilter={changeFilter}
                    />
                    <FilterSelect
                        id={"status"}
                        list={lang === "ko" ? FILTERS.STATUS : FILTERS.STATUS_ENG}
                        selected={arcanaFilter.status}
                        changeFilter={changeFilter}
                        forceWidth={"120px"}
                    />
                    <SearchBox changeQuery={setQuery} placeholder={getUIText(lang, "search.deck")} />
                </div>

                {/* TODO : card list */}
                <div className={styles["arcana-list-container"]}>
                    {arcanaIds.map((id) => {
                        const arcana = arcanaEntities[id];
                        return (
                            <Card
                                lang={lang}
                                arcana={arcana}
                                clickEvent={() => dispatch(toggleArcana(arcana))}
                                isOffImage={false}
                                showFavorite={false}
                                key={v4()}
                            />
                        );
                    })}
                </div>
            </div>

            <ScrollUpButton />
            <Footer />
        </div>
    );
}
