import { createSlice } from "@reduxjs/toolkit";
import originData from "../../../data/journey_items.json";
import FILTERS from "../../../data/filter_config.json";
import SORT_LIST from "../../../data/sort_config.json";
import { replaceColorTag } from "../../../functions/stringFunctions";
import { CONSUME_TYPE, ITEM_REGION } from "../../../constants";

const rarity_score = {
    IG_LEGENDARY: 0,
    IG_UNIQUE: 1,
    IG_RARE: 2,
};

const type_score = {
    NT_CHARM: 0,
    NT_COOK: 1,
    NT_TRAINING_EXP_ITEM: 2,
    NT_VALUABLES: 3,
};

const lang = localStorage.getItem("language") || "ko";
const locale = lang === "ko" ? "ko-KR" : "en-US";

const normalizeItems = (originData) => {
    const ids = [];
    const entities = {};

    originData.forEach((data) => {
        ids.push(data.id);

        const parts = [data.name.ko, data.description.ko];
        const parts_ENG = [data.name.en, data.description.en];

        if (data.charm_info) {
            data.charm_info.se_list.forEach((se) => {
                const cleanedSe = replaceColorTag(se);
                parts.push(replaceColorTag(se.ko));
                parts_ENG.push(replaceColorTag(se.en));
            });
        }

        if (data.stats) {
            parts.push(...data.stats.map((stat) => `${CONSUME_TYPE[stat.type].ko} ${stat.value < 0 ? stat.value : `+${stat.value}`}`));
            parts_ENG.push(...data.stats.map((stat) => `${CONSUME_TYPE[stat.type].en} ${stat.value < 0 ? stat.value : `+${stat.value}`}`));
        }

        if (data.events) {
            parts.push(...data.events.map((e) => e.ko));
            parts_ENG.push(...data.events.map((e) => e.en));
        }
        if (data.regions) {
            parts.push(...data.regions.map((e) => ITEM_REGION[e].ko));
            parts_ENG.push(...data.regions.map((e) => ITEM_REGION[e].en));
        }

        entities[data.id] = {
            ...data,
            searchText: parts.join(" "),
            searchText_ENG: parts_ENG.join(" "),
        };
    });

    ids.sort((a, b) => {
        const typeDiff = type_score[entities[a].type] - type_score[entities[b].type];
        if (typeDiff !== 0) return typeDiff;

        const rarityDiff = rarity_score[entities[a].rarity] - rarity_score[entities[b].rarity];
        if (rarityDiff !== 0) return rarityDiff;

        return entities[a].name[lang].localeCompare(entities[b].name[lang], locale);
    });

    return { ids, entities };
};

const normalized = normalizeItems(originData);

const itemSlice = createSlice({
    name: "items",
    initialState: {
        ids: normalized.ids,
        entities: normalized.entities,
        filter: {
            type: FILTERS.ITEM_TYPE[0],
            sort: SORT_LIST.ITEM_SORT[0],
        },
    },
    reducers: {
        setSortFilter: (state, action) => {
            state.filter.sort = action.payload.obj;
        },
        setTypeFilter: (state, action) => {
            state.filter.type = action.payload.obj;
        },
    },
});

export const { setSortFilter, setTypeFilter } = itemSlice.actions;

export default itemSlice.reducer;
