// import saviors from "../data/saviors.json";
import CONFIG from "../data/modal_savior_status_config.json";
import { getSaviorStatRanks } from "./getSaviorStatRanks";

let maxStat = null;
let ranks = getSaviorStatRanks();

const construct = () => {
    if (!maxStat) {
        maxStat = {};

        CONFIG.STATUS.forEach((config) => {
            const sorted = ranks.sort((a, b) => b.status[config.value] - a.status[config.value]);

            maxStat[config.value] = sorted[0].status[config.value];
        });
    }
};

construct();

const getSaviorStatProgress = (savior, statName) => {
    const found = ranks.find((e) => e.id === savior.id);
    return Math.min(100, (found.status[statName] / maxStat[statName]) * 100);
};

export default getSaviorStatProgress;
